mapper.select:
SELECT device.entrance_id entranceId, CASE device.entrance_id WHEN 1 THEN 'Astana' WHEN 2 THEN 'Alamty' ELSE - 1 END AS area, (netflow.INOCTETS_SPEED+ netflow.OUTOCTETS_SPEED) as sum, netflow.RECV_TIME reportTime FROM ntc_device_info device LEFT JOIN ( SELECT netflow.INOCTETS_SPEED INOCTETS_SPEED, netflow.OUTOCTETS_SPEED OUTOCTETS_SPEED, netflow.RECV_TIME, netflow.NODE_IP FROM traffic_netflow_port_info netflow
netflow.RECV_TIME>#{startTime} and netflow.RECV_TIME<=#{endTime}
) netflow ON device.manager_ip = netflow.NODE_IP WHERE netflow.RECV_TIME IS NOT NULL

SELECT report.service,report.report_time,report.sum,dic.service_name_zh,dic.service_name_zh,dic.service_name_ru from ( SELECT service,report_time,sum(sum) as sum FROM ntc_service_report
AND service in (${searchService})
AND report_time >= #{searchReportStartTime}
AND report_time < #{searchReportEndTime}
GROUP BY service, report_time order by report_time ASC,sum DESC) report LEFT JOIN ntc_service_dic dic on report.service = dic.service_code

SELECT 'drop' AS label, IFNULL( ( sum(reject_num) + SUM(drop_conn_num) ), 0 ) AS sum,#{startTime} as reportTime FROM ntc_total_report
report_time>#{startTime} and report_time<=#{endTime}
order by report_time asc;

SELECT 'drop' AS label, IFNULL( ( sum(reject_num) + SUM(drop_conn_num) ), 0 ) AS sum,report_time as reportTime FROM ntc_total_report
report_time>#{startTime} and report_time<=#{endTime}
GROUP BY report_time order by report_time asc;
